#!/usr/bin/env python3
"""Refresh the C-only WebGL ABI used outside ANGLE's translation unit."""

from pathlib import Path
import re

repo = Path(__file__).resolve().parent.parent
source = (repo / 'webgl/native_egl.h').read_text()
signatures = re.findall(r'^VOX_EGL_LINKAGE ([^;{}]+?\([^{};]*\))\s*\{', source, re.MULTILINE)
if not signatures:
    raise SystemExit('No native WebGL functions found')
(repo / 'webgl/native_egl_api.h').write_text(
    '// Native WebGL service ABI; generated by tools/generate_webgl_api.py.\n#pragma once\n#include <stdint.h>\n'
    + ''.join(signature + ';\n' for signature in signatures))
